#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_appendf_resize_failure(void) {
    // Setup: create a valid buffer
    buffer_t *buf = buffer_new_with_size(8);
    TEST_ASSERT_NOT_NULL(buf);

    // Fill buffer with some data
    const char *initial = "abc";
    memcpy(buf->data, initial, 3);
    buf->data[3] = '\0';

    // Prepare format string and argument
    const char *fmt = "%d";
    int value = 12345;

    // Calculate allocations:
    // buffer_new_with_size(8): 2 allocations (struct + data)
    // buffer_appendf will call buffer_resize, which will call realloc
    // We want the realloc in buffer_resize to fail, so fail after 2 allocations
    malloc_fail_after(2);

    // Test: buffer_appendf should return -1 on resize failure
    int ret = buffer_appendf(buf, fmt, value);
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Buffer should still contain the original data
    helper_assert_buffer_string_equals(buf, "abc");

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_appendf_resize_failure);
    return UNITY_END();
}

